 };

+typedef enum {
+  ACK = 0,
+  NACK = 1,
+  AccessDenied = 2,
+  CannotRespond = 3,
+
+  ACK_OneByte = 128,
+  NACK_OneByte = 129,
+  AccessDenied_OneByte = 130,
